dashboard.definition:
{
	"title": "Windows Events",
	"description": "",
	"inputs": {
		"input_global_trp": {
			"options": {"defaultValue": "-30d@d,now", "token": "global_time"},
			"title": "Global Time Range",
			"type": "input.timerange"
		},
		"input_nav_dropdown": {
			"type": "input.dropdown",
			"title": "Navigate to Dashboard",
			"options": {
				"items": [
					{"label": "Overview", "value": "logserv_overview"},
					{"label": "DNS Analytics", "value": "logserv_dns_analytics"},
					{"label": "HANA Audit", "value": "logserv_hana_audit"},
					{"label": "HANA Trace", "value": "logserv_hana_trace"},
					{"label": "Web Dispatcher", "value": "logserv_web_dispatcher"},
					{"label": "Host Details", "value": "logserv_host_details"},
					{"label": "ABAP Security", "value": "logserv_abap_security"},
					{"label": "ABAP Operations", "value": "logserv_abap_operations"},
					{"label": "SAP Services", "value": "logserv_sap_services"},
					{"label": "Cloud Connector", "value": "logserv_cloud_connector"},
					{"label": "Linux", "value": "logserv_linux"},
					{"label": "Proxy", "value": "logserv_proxy"},
					{"label": "Environment Health", "value": "logserv_environment_health"}
				],
				"token": "nav_target"
			}
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"earliest": "$global_time.earliest$",
						"latest": "$global_time.latest$"
					}
				}
			}
		}
	},
	"visualizations": {
		"viz_kpi_total": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_kpi_total"},
			"title": "Total Events",
			"options": {"majorValue": "> primary | seriesByName('total') | lastPoint()", "backgroundColor": "transparent", "sparklineDisplay": "off", "trendDisplay": "off"}
		},
		"viz_kpi_critical": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_kpi_critical"},
			"title": "Critical / Error",
			"options": {"majorValue": "> primary | seriesByName('critical_count') | lastPoint()", "majorColor": "#dc4e41", "backgroundColor": "transparent", "sparklineDisplay": "off", "trendDisplay": "off"}
		},
		"viz_kpi_hosts": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_kpi_hosts"},
			"title": "Active Hosts",
			"options": {"majorValue": "> primary | seriesByName('hosts') | lastPoint()", "backgroundColor": "transparent", "sparklineDisplay": "off", "trendDisplay": "off"}
		},
		"viz_volume_by_log": {
			"type": "splunk.line",
			"dataSources": {"primary": "ds_volume_by_log"},
			"title": "Event Volume by Log",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {"backgroundColor": "transparent", "xAxisTitleVisibility": "hide", "yAxisTitleVisibility": "hide"}
		},
		"viz_severity": {
			"type": "splunk.column",
			"dataSources": {"primary": "ds_severity"},
			"title": "Severity Distribution Over Time",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent", "stackMode": "stacked",
				"xAxisTitleVisibility": "hide", "yAxisTitleVisibility": "hide",
				"seriesColorsByField": {"critical": "#af575a", "error": "#dc4e41", "warning": "#f1813f", "information": "#0877a6"}
			}
		},
		"viz_top_events": {
			"type": "splunk.table",
			"dataSources": {"primary": "ds_top_events"},
			"title": "Top Event Codes",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)",
					"headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
					"rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)",
					"headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)"
				}
			}
		},
		"viz_security_actions": {
			"type": "splunk.column",
			"dataSources": {"primary": "ds_security_actions"},
			"title": "Security Event Actions",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {"backgroundColor": "transparent", "stackMode": "stacked", "xAxisTitleVisibility": "hide", "yAxisTitleVisibility": "hide"}
		},
		"viz_top_users": {
			"type": "splunk.table",
			"dataSources": {"primary": "ds_top_users"},
			"title": "Top Users",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)",
					"headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
					"rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)",
					"headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)"
				}
			}
		},
		"viz_service_events": {
			"type": "splunk.table",
			"dataSources": {"primary": "ds_service_events"},
			"title": "Service Events",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)",
					"headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
					"rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)",
					"headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)"
				}
			}
		},
		"viz_powershell": {
			"type": "splunk.line",
			"dataSources": {"primary": "ds_powershell"},
			"title": "PowerShell Activity",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {"backgroundColor": "transparent", "xAxisTitleVisibility": "hide", "yAxisTitleVisibility": "hide"}
		},
		"viz_rect_r1l": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_rect_r1r": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_rect_r2l": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_rect_r2m": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_rect_r2r": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_rect_r3l": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_rect_r3r": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_nav_go": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_nav_go"},
			"options": {
				"majorValue": "> primary | seriesByName('label') | lastPoint()",
				"backgroundColor": "#0877a6", "majorColor": "#ffffff",
				"sparklineDisplay": "off", "trendDisplay": "off", "majorFontSize": 14
			},
			"eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "/app/splunk_app_sap_logserv/$nav_target$?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$", "newTab": false}}]
		}
	},
	"dataSources": {
		"ds_kpi_total": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"XmlWinEventLog\" | stats count as total"}
		},
		"ds_kpi_critical": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"XmlWinEventLog\" | where severity IN (\"critical\", \"error\") | stats count as critical_count"}
		},
		"ds_kpi_hosts": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"XmlWinEventLog\" | stats dc(host) as hosts"}
		},
		"ds_volume_by_log": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"XmlWinEventLog\" | timechart span=1d count by source"}
		},
		"ds_severity": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"XmlWinEventLog\" | where isnotnull(severity) | timechart span=1d count by severity"}
		},
		"ds_top_events": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"XmlWinEventLog\" | stats count as Events first(signature) as Description by EventCode | sort -Events | head 20 | rename EventCode as \"Event Code\""}
		},
		"ds_security_actions": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"XmlWinEventLog\" source=\"WinEventLog:Security\" action=* | timechart span=1d count by action"}
		},
		"ds_top_users": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"XmlWinEventLog\" | where isnotnull(user) AND user!=\"-\" | stats count as Events dc(EventCode) as \"Event Codes\" values(action) as Actions by user | sort -Events | head 20 | rename user as User"}
		},
		"ds_service_events": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"XmlWinEventLog\" source=\"WinEventLog:System\" EventCode IN (7036, 7034, 7031) | rex field=_raw \"<Data Name='param1'>(?<svc_name>[^<]+)</Data>\" | rex field=_raw \"<Data Name='param2'>(?<svc_state>[^<]+)</Data>\" | where isnotnull(svc_name) | stats count as Events latest(svc_state) as \"Last State\" by svc_name | sort -Events | head 20 | rename svc_name as \"Service Name\""}
		},
		"ds_powershell": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"XmlWinEventLog\" source=\"WinEventLog:Powershell\" | timechart span=1d count as \"PowerShell Events\""}
		},
		"ds_nav_go": {
			"type": "ds.search",
			"options": {"query": "| makeresults | eval label=\"Go >\"", "queryParameters": {"earliest": "-1m", "latest": "now"}}
		}
	},
	"layout": {
		"globalInputs": ["input_global_trp", "input_nav_dropdown"],
		"layoutDefinitions": {
			"layout_1": {
				"options": {"height": 1200, "width": 1920},
				"structure": [
					{"item": "viz_nav_go", "type": "block", "position": {"x": 1790, "y": 0, "w": 120, "h": 35}},
					{"item": "viz_kpi_total", "type": "block", "position": {"x": 10, "y": 45, "w": 300, "h": 90}},
					{"item": "viz_kpi_critical", "type": "block", "position": {"x": 320, "y": 45, "w": 300, "h": 90}},
					{"item": "viz_kpi_hosts", "type": "block", "position": {"x": 630, "y": 45, "w": 300, "h": 90}},
					{"item": "viz_rect_r1l", "type": "block", "position": {"x": 10, "y": 150, "w": 940, "h": 340}},
					{"item": "viz_volume_by_log", "type": "block", "position": {"x": 20, "y": 155, "w": 920, "h": 330}},
					{"item": "viz_rect_r1r", "type": "block", "position": {"x": 960, "y": 150, "w": 950, "h": 340}},
					{"item": "viz_severity", "type": "block", "position": {"x": 970, "y": 155, "w": 930, "h": 330}},
					{"item": "viz_rect_r2l", "type": "block", "position": {"x": 10, "y": 505, "w": 620, "h": 340}},
					{"item": "viz_top_events", "type": "block", "position": {"x": 20, "y": 510, "w": 600, "h": 330}},
					{"item": "viz_rect_r2m", "type": "block", "position": {"x": 640, "y": 505, "w": 640, "h": 340}},
					{"item": "viz_security_actions", "type": "block", "position": {"x": 650, "y": 510, "w": 620, "h": 330}},
					{"item": "viz_rect_r2r", "type": "block", "position": {"x": 1290, "y": 505, "w": 620, "h": 340}},
					{"item": "viz_top_users", "type": "block", "position": {"x": 1300, "y": 510, "w": 600, "h": 330}},
					{"item": "viz_rect_r3l", "type": "block", "position": {"x": 10, "y": 860, "w": 950, "h": 330}},
					{"item": "viz_service_events", "type": "block", "position": {"x": 20, "y": 865, "w": 930, "h": 320}},
					{"item": "viz_rect_r3r", "type": "block", "position": {"x": 970, "y": 860, "w": 940, "h": 330}},
					{"item": "viz_powershell", "type": "block", "position": {"x": 980, "y": 865, "w": 920, "h": 320}}
				],
				"type": "absolute"
			}
		},
		"options": {},
		"tabs": {"items": [{"label": "New tab", "layoutId": "layout_1"}]}
	}
}
